(function(){
 'use strict';
 const account=DamDaAccount,adapter=DamDaModel;
 let installed=null,original=null,categories=['미분류'],busy=false,notice='',shared=null,sharedTicket=0,published=null,guest=false;
 const guestKey='damda-guest-workspace';
 const guestRead=()=>{try{return JSON.parse(localStorage.getItem(guestKey)||'null');}catch{return null;}};
 const guestWrite=()=>{try{localStorage.setItem(guestKey,JSON.stringify({model,collection,customPresets,categories,welcomeInitialized:true}));}catch{notify(t('체험 내용을 저장하지 못했습니다.','Demo data could not be saved.'));}};
 const guestShareRead=id=>{try{return JSON.parse(localStorage.getItem('damda-guest-shares')||'{}')[id]||null;}catch{return null;}};
 const guestStart=()=>{const saved=guestRead();if(saved){model=saved.model;collection=saved.collection||[];customPresets=saved.customPresets||[];categories=saved.categories||['미분류'];}else{model=adapter.empty();collection=[];customPresets=[];categories=['미분류'];}if(!saved?.welcomeInitialized&&!collection.some(c=>c.id==='damda-welcome-v1')){const welcome=adapter.welcomeCard();collection.unshift({...adapter.fromSnapshot(welcome.data),id:welcome.id,group:welcome.tab,savedAt:welcome.savedAt,_raw:welcome});}original=null;installed=null;signed=true;guest=true;guestWrite();preset='';filter='전체';query='';location.hash='home';render();};
 const baseRender=render,baseShell=shell,baseSettings=settings,baseBook=book,basePreset=applyPreset;
 const baseURL=()=>location.origin+location.pathname;
 const rawRoute=()=>location.hash.slice(1).split('?')[0]||'home';
 route=()=>rawRoute();
 const err=e=>({invalid_credentials:t('이메일 또는 비밀번호를 확인해 주세요.','Check your email and password.'),email_not_confirmed:t('계정의 이메일 확인 상태를 관리자에게 확인해 주세요.','Ask the administrator to check this account’s confirmation status.'),user_already_exists:t('이미 가입된 이메일입니다. 로그인해 주세요.','This email is already registered. Sign in.'),weak_password:t('비밀번호가 서버의 보안 조건을 충족하지 않습니다.','The password does not meet the server requirements.'),same_password:t('현재 비밀번호와 다른 비밀번호를 입력해 주세요.','Choose a different password.'),over_email_send_rate_limit:t('메일 요청이 많습니다. 잠시 후 다시 시도해 주세요.','Too many email requests. Try again later.'),over_request_rate_limit:t('요청이 많습니다. 잠시 후 다시 시도해 주세요.','Too many requests. Try again later.'),unexpected_failure:t('요청을 처리하지 못했습니다. 잠시 후 다시 시도해 주세요.','The request failed. Please try again.')}[e?.code]||e?.message||t('요청을 처리하지 못했습니다.','The request failed.'));
 function showError(message){const el=$('#dialog[open] #form-error')||$('#form-error');if(el)el.textContent=message;else notify(message);}
 async function run(fn,button){if(busy)return;busy=true;if(button)button.disabled=true;try{await fn();}catch(e){showError(err(e));}finally{busy=false;if(button?.isConnected)button.disabled=false;}}
 function validPassword(value){const count=[/[A-Z]/,/[a-z]/,/[0-9]/,/[^A-Za-z0-9\s]/].filter(r=>r.test(value)).length;return {count,valid:value.length>=8&&value.length<=128&&count>=2,level:value.length<8||count<2?0:value.length>=12&&count>=3?2:1};}
 function checkPassword(value){if(!validPassword(value).valid)throw Error(t('비밀번호는 8자 이상, 대문자·소문자·숫자·특수문자 중 2종류 이상이어야 합니다.','Use at least 8 characters and 2 character types.'));}
 const strength=()=>'<div id="password-strength" class="password-guide" aria-live="polite">'+t('8자 이상 · 대문자·소문자·숫자·특수문자 중 2종류 이상','8+ characters · at least 2 types: uppercase, lowercase, number, symbol')+'</div>';
 const passwordField=(id,label)=>'<label>'+label+'<input id="'+id+'" name="password" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label>';
 const formError=()=>'<p id="form-error" role="alert">'+esc(notice)+'</p>';
 function authContent(){const recovery=account.state.recovery,signup=rawRoute()==='signup';
  if(recovery)return '<div class="eyebrow">A FRESH START</div><h2>'+t('새 비밀번호 설정','Set a new password')+'</h2><form id="recovery-form">'+passwordField('new-password',t('새 비밀번호','New password'))+strength()+'<label>'+t('비밀번호 확인','Confirm password')+'<input name="confirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label>'+formError()+'<button class="button primary full">'+t('비밀번호 변경','Update password')+icon('arrow')+'</button></form>';
  if(signup)return '<div class="eyebrow">YOUR NEXT CONNECTION</div><h2>'+t('나를 담는 첫걸음.','Your first connection.')+'</h2><p class="muted">'+t('계정을 만들고 나만의 명함을 저장하세요.','Create an account for your own cards.')+'</p><form id="signup-form"><label>'+t('이름 또는 닉네임','Name or nickname')+'<input name="displayName" autocomplete="name" maxlength="30" required></label><label>'+t('이메일','Email')+'<input name="email" type="email" autocomplete="email" maxlength="254" required></label>'+passwordField('signup-password',t('비밀번호','Password'))+strength()+'<label>'+t('비밀번호 확인','Confirm password')+'<input name="confirm" type="password" autocomplete="new-password" minlength="8" maxlength="128" required></label><label class="check-row consent"><input type="checkbox" required>'+t('프로필과 명함함은 계정에 저장되며, 공유한 명함은 링크를 아는 사람이 볼 수 있음을 확인했습니다.','I understand my profile is private and shared cards can be viewed by anyone with the link.')+'</label>'+formError()+'<button class="button primary full">'+t('회원가입','Create account')+icon('arrow')+'</button></form><p class="auth-link">'+t('이미 계정이 있나요?','Already have an account?')+' <a href="#login">'+t('로그인','Sign in')+'</a></p>';
    return '<div class="eyebrow">WELCOME TO YOUR WORKSPACE</div><h2>'+t('당신의 다음 명함.','Your next business card.')+'</h2><p class="muted">'+t('어디서든 이어지는 나만의 워크스페이스.','Your workspace, wherever you are.')+'</p><form id="login-form"><label>'+t('이메일','Email')+'<input id="login-email" name="email" type="email" autocomplete="username" maxlength="254" required placeholder="hello@example.com"></label><label>'+t('비밀번호','Password')+'<span class="password-input"><input name="password" type="password" autocomplete="current-password" maxlength="128" required><button type="button" data-action="show-password">'+t('보기','Show')+'</button></span></label>'+formError()+'<button class="button primary full">'+t('로그인','Sign in')+icon('arrow')+'</button><a class="button full" href="#signup">'+t('회원가입','Create account')+icon('arrow')+'</a></form><div class="auth-options"><button type="button" class="text-button" data-prod="forgot-dialog">'+t('비밀번호를 잊으셨나요?','Forgot your password?')+'</button></div><button type="button" class="button full" data-prod="guest-start">'+t('로그인 없이 체험하기','Try without signing in')+icon('arrow')+'</button><p class="local-note">'+t('체험 내용은 이 브라우저에만 저장됩니다.','Demo data is saved only in this browser.')+'</p>';
 }
 function authLayout(content){return '<div class="login-shell"><header class="login-header">'+brand()+'<span class="eyebrow">YOUR DIGITAL IDENTITY</span>'+settingButton()+'</header><main id="main" class="login-main"><section class="login-story"><div class="eyebrow"><span class="tiny-block"></span> YOUR NEXT INTRODUCTION</div><h1>'+t('나를 담다.<br>연결을 만들다.','Your identity.<br>Your next connection.')+'</h1><p>'+t('첫인상은 더 명확하게.<br>당신의 가능성을 한 장에 담으세요.','A clearer first impression.<br>Make space for what comes next.')+'</p><div class="login-art"><div class="art-card"><div class="card-brand">DamDa<span>YOUR IDENTITY, REDEFINED</span></div><div class="art-card-name">Hello<span>YOUR NEXT CONNECTION</span></div><div class="art-bottom"><span>MAKE SOMETHING<br>WORTH CONNECTING.</span><span class="art-mark">↗</span></div></div><div class="art-note">01 — THE SHAPE OF YOU</div></div></section><section class="login-form-area">'+content+'</section></main><footer class="login-footer"><span>© 2026 DamDa</span><span>DESIGNED FOR EVERY CONNECTION.</span></footer></div>';}
 login=()=>authLayout(authContent());
 function syncStatus(){const state=account.state,b=$('#cloud-save-status');if(!b)return;if(guest){b.textContent=t('이 브라우저에 저장됨','Saved on this browser');b.dataset.failed='false';b.title=t('체험 내용은 현재 브라우저에만 저장됩니다.','Demo data is saved only in this browser.');b.disabled=false;return;}b.textContent=state.error?t('저장 실패 · 다시 저장','Save failed · Retry'):state.saving||state.dirty?t('저장 중…','Saving…'):t('계정에 저장됨','Saved to account');b.dataset.failed=state.error?'true':'false';b.title=state.error||'';b.disabled=state.saving;const warning=$('#save-warning');if(warning){warning.hidden=!state.error;warning.querySelector('p').textContent=state.error;}}
 shell=(page,content)=>baseShell(page,content).replace(/<span class="save-indicator">[\s\S]*?<\/span><\/span>/,'<button id="cloud-save-status" class="save-indicator" data-prod="retry-save" aria-live="polite"></button>').replace('<main id="main">','<main id="main"><div id="save-warning" class="save-warning" hidden><p></p><button class="text-button" data-prod="backup">'+t('현재 내용 백업','Back up current changes')+'</button><button class="text-button" data-prod="reload-account">'+t('새로 불러오기','Reload account')+'</button></div>');
 persist=function(){try{localStorage.setItem(key,JSON.stringify(prefs));}catch{}if(guest){guestWrite();syncStatus();return;}if(signed&&original){account.save(adapter.encode(model,collection,customPresets,categories,original));}syncStatus();};
 settings=function(){baseSettings();if(guest)$('#dialog').insertAdjacentHTML('beforeend','<div class="account-settings"><p>'+t('로그인 없이 체험 중','Demo mode without sign-in')+'</p><button class="button full" data-prod="guest-signup">'+t('계정 만들고 저장하기','Create an account to keep this')+'</button></div>');else if(signed)$('#dialog').insertAdjacentHTML('beforeend','<div class="account-settings"><p>'+esc(account.state.user.email)+'</p><button class="button full" data-prod="password-dialog">'+t('비밀번호 변경','Change password')+'</button></div>');};
 applyPreset=function(id){if(id.startsWith('custom-')){const p=customPresets[+id.slice(7)];if(!p)return;model.visible=Object.keys(adapter.fieldMap).filter(k=>p.labels?.includes(adapter.fieldMap[k])||p.visible?.includes(k));model.custom.forEach(f=>f.selected=(p.labels||[]).includes(f.label));if(p.nameMode)model.identity=p.nameMode;if(typeof p.showName==='boolean')model.showName=p.showName;preset=id;persist();render();}else{model.custom.forEach(f=>f.selected=false);basePreset(id);}};

 let collectionMode='edit',modalFolder='전체',modalTarget='미분류',modalSelection=new Set();
 const allCategories=()=>[...new Set(['미분류',...categories,...collection.map(c=>c.group||'미분류')])].filter(v=>v&&v!=='전체'&&v!=='__new__');
 const categoryNameValid=(name,old)=>name&&name.length<=30&&!['전체','__new__'].includes(name)&&(!allCategories().includes(name)||name===old);
 const modalVisible=()=>collection.filter(c=>modalFolder==='전체'||(c.group||'미분류')===modalFolder);
 function syncModalSelection(){const visible=modalVisible(),all=$('[data-modal-all]');if(!all)return;const count=visible.filter(c=>modalSelection.has(c.id)).length;all.checked=visible.length>0&&count===visible.length;all.indeterminate=count>0&&count<visible.length;all.disabled=!visible.length;$('#modal-selection-count').textContent=t(modalSelection.size+'개 선택',modalSelection.size+' selected');$('#modal-apply').disabled=!modalSelection.size;}
 function openCollectionEditor(folder=modalFolder){modalFolder=folder;const deleting=collectionMode==='delete';openDialog('<div class="eyebrow">'+(deleting?'DELETE CARDS':'ORGANIZE YOUR CONNECTIONS')+'</div><h2>'+t(deleting?'삭제 모드':'편집 모드',deleting?'Delete cards':'Edit collection')+'</h2><p class="muted">'+t(deleting?'삭제할 명함을 선택하세요. 삭제 전에 한 번 더 확인합니다.':'명함을 선택하고 원하는 분류로 한 번에 이동하세요.',deleting?'Select cards to delete. You will confirm before deletion.':'Select cards and move them to a category together.')+'</p><div class="collection-modal-folders">'+['전체',...allCategories()].map(g=>'<button class="button" aria-pressed="'+(folder===g)+'" data-modal-folder="'+esc(g)+'">'+esc(g==='전체'?t('전체','All'):g)+' <small>'+collection.filter(c=>g==='전체'||(c.group||'미분류')===g).length+'</small></button>').join('')+'</div><div class="collection-modal-selection"><label><input type="checkbox" data-modal-all> '+t('현재 분류 전체 선택','Select this category')+'</label><span id="modal-selection-count" role="status"></span></div><div class="collection-modal-list">'+(modalVisible().length?modalVisible().map(c=>'<label class="collection-modal-card"><input type="checkbox" data-modal-card="'+esc(c.id)+'" '+(modalSelection.has(c.id)?'checked':'')+'><span><b>'+esc(c.name||'DamDa')+'</b><small>'+esc(c.company||c.role||t('저장된 명함','Saved card'))+'</small></span><em>'+esc(c.group||'미분류')+'</em></label>').join(''):'<div class="collection-modal-empty">'+t('이 분류에 저장된 명함이 없습니다.','No cards in this category.')+'</div>')+'</div><div class="collection-modal-actions">'+(!deleting?'<label>'+t('이동할 분류','Move to')+'<select id="modal-category">'+allCategories().map(g=>'<option value="'+esc(g)+'" '+(g===modalTarget?'selected':'')+'>'+esc(g)+'</option>').join('')+'</select></label>':'<p class="muted">'+t('삭제한 명함은 복구할 수 없습니다.','Deleted cards cannot be recovered.')+'</p>')+'<button id="modal-apply" class="button '+(deleting?'danger':'primary')+'" data-prod="'+(deleting?'modal-delete':'modal-category-apply')+'">'+t(deleting?'선택 삭제':'선택 명함 이동',deleting?'Delete selected':'Move selected')+'</button></div>','collection-dialog');syncModalSelection();}
 function openCategoryMode(folder='전체'){openCollectionEditor(folder);}
 const originalCollectionItems=collectionItems;
 collectionItems=()=>originalCollectionItems().replace(/<label class="collection-select">[\s\S]*?<\/label>/g,'');
 book=function(){let html=baseBook();html=html.replace(/<div class="collection-bulk">[\s\S]*?<\/div>(?=<div id="collection-grid")/,'');const controls='<div class="category-actions" aria-label="'+t('명함함 관리','Collection tools')+'"><div><button class="button" data-prod="collection-edit">'+t('편집 모드','Edit mode')+'</button><button class="button danger" data-prod="collection-delete">'+t('삭제 모드','Delete mode')+'</button></div><div><button class="button" data-prod="category-add">'+icon('plus')+t('분류 추가','Add category')+'</button><button class="button" data-prod="category-manage">'+icon('settings')+t('분류 관리','Manage categories')+'</button></div></div>';html=html.replace('<div class="collection-controls">',controls+'<div class="collection-controls">');html=html.replace(/<div class="filter-tabs">[\s\S]*?<\/div><label class="search">/,'<div class="filter-tabs">'+['전체',...allCategories()].map(v=>'<button data-filter="'+esc(v)+'" aria-pressed="'+(filter===v)+'">'+esc(v==='전체'?t('전체','All'):v)+' <small>'+collection.filter(c=>v==='전체'||(c.group||'미분류')===v).length+'</small></button>').join('')+'</div><label class="search">');if(guest)html=html.replace(t('계정에 보관한 명함입니다. 다른 기기에서도 확인할 수 있습니다.','Your saved cards are available on other devices.'),t('체험 명함은 이 브라우저에만 저장됩니다.','Demo cards are saved only in this browser.'));return html;};
 document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-modal-card]')){if(el.checked)modalSelection.add(el.dataset.modalCard);else modalSelection.delete(el.dataset.modalCard);syncModalSelection();}if(el.matches('[data-modal-all]')){modalVisible().forEach(c=>el.checked?modalSelection.add(c.id):modalSelection.delete(c.id));document.querySelectorAll('[data-modal-card]').forEach(box=>box.checked=modalSelection.has(box.dataset.modalCard));syncModalSelection();}if(el.id==='modal-category')modalTarget=el.value;});
 function adopt(state){const decoded=adapter.decode(state.account);model=decoded.model;collection=decoded.collection;customPresets=decoded.presets;categories=decoded.tabs;original=structuredClone(state.account);installed=state.account;signed=true;preset='';filter='전체';query='';}
 render=function(){applyPrefs();const state=account.state;if(rawRoute()==='card'){renderShared();return;}if(guest){if(['login','signup',''].includes(rawRoute()))history.replaceState(null,'',location.pathname+location.search+'#home');baseRender();syncStatus();return;}if(state.recovery){$('#app').innerHTML=login();return;}if(state.phase==='loading'){$('#app').innerHTML=authLayout('<p role="status">'+t('계정을 확인하고 있습니다…','Loading your account…')+'</p>');return;}if(state.phase==='error'){$('#app').innerHTML=authLayout('<h2>'+t('계정 연결 확인','Check your connection')+'</h2><p role="alert">'+esc(state.error)+'</p><div class="auth-options"><button class="button" data-prod="retry-load">'+t('다시 시도','Retry')+'</button><button class="text-button" data-prod="logout">'+t('로그아웃','Sign out')+'</button></div>');return;}if(signed&&['login','signup',''].includes(rawRoute())){history.replaceState(null,'',location.pathname+location.search+'#home');}baseRender();syncStatus();};
 async function afterAuth(){if(account.state.phase!=='ready')return;notice='';const pending=sessionStorage.getItem('damda-pending-card');if(pending){try{const data=await account.readCard(pending);await storeReceived(pending,data);sessionStorage.removeItem('damda-pending-card');location.hash='book';}catch(e){sessionStorage.removeItem('damda-pending-card');notify(err(e));location.hash='home';}}else{location.hash='home';render();}}
 account.subscribe(state=>{if(state.phase==='ready'){if(installed!==state.account){adopt(state);render();}else syncStatus();}else if(state.phase==='anonymous'){installed=null;original=null;signed=false;model=adapter.empty();collection=[];customPresets=[];published=null;categories=['미분류'];if($('#dialog').open)closeDialog();notice=state.error||'';render();}else render();});
 document.addEventListener('submit',e=>{
  const f=e.target;if(!['login-form','signup-form','recovery-form','change-password-form','category-form','preset-form','forgot-form'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();
  if(f.id==='category-form'){const value=f.elements.category.value.trim();if(!categoryNameValid(value)){showError(t('다른 분류 이름을 입력해 주세요.','Choose a different category name.'));return;}categories.push(value);persist();closeDialog();render();return;}
  if(f.id==='preset-form'){customPresets.push({id:crypto.randomUUID(),name:f.elements.name.value.trim(),visible:[...model.visible],labels:[...model.visible.map(k=>adapter.fieldMap[k]),...model.custom.filter(x=>x.selected).map(x=>x.label)],nameMode:model.identity,showName:model.showName});persist();closeDialog();render();return;}
  if(f.id==='forgot-form'){run(async()=>{const email=f.elements.email.value.trim();if(!email||!f.elements.email.checkValidity())throw Error(t('올바른 이메일을 입력해 주세요.','Enter a valid email.'));await account.resetPassword(email);f.innerHTML='<p role="status">'+t('가입된 이메일이라면 비밀번호 재설정 링크가 발송됩니다. 메일함(스팸함 포함)을 확인해 주세요.','If this email is registered, a reset link is on its way. Check your inbox and spam folder.')+'</p>';},f.querySelector('button'));return;}
  run(async()=>{notice='';showError('');if(f.id==='login-form'){await account.login(f.elements.email.value.trim(),f.elements.password.value);await afterAuth();return;}const password=f.elements.password.value;checkPassword(password);if(password!==f.elements.confirm.value)throw Error(t('비밀번호가 일치하지 않습니다.','Passwords do not match.'));if(f.id==='signup-form'){await account.signup(f.elements.email.value.trim(),password,f.elements.displayName.value.trim());await afterAuth();}else{await account.changePassword(password);if($('#dialog').open)closeDialog();notify(t('비밀번호를 변경했습니다.','Password updated.'));render();}},f.querySelector('[type=submit],button.primary'));
 },true);
 document.addEventListener('change',e=>{if(e.target.id!=='card-group')return;const row=$('#card-group-new-row');row.hidden=e.target.value!=='__new__';if(!row.hidden)$('#card-group-new').focus();});
 document.addEventListener('input',e=>{if(!['signup-password','new-password','change-password'].includes(e.target.id))return;const s=validPassword(e.target.value),guide=$('#password-strength');if(guide){guide.dataset.level=s.level;guide.textContent=t('비밀번호 강도: ','Password strength: ')+[t('약함','Weak'),t('중간','Medium'),t('강력','Strong')][s.level]+' · '+(e.target.value.length>=8?'✓ ':'○ ')+t('8자 이상','8+ characters')+' · '+(s.count>=2?'✓ ':'○ ')+t('2종류 이상','2+ character types');}});
 function sameCard(a,b){return JSON.stringify(a)===JSON.stringify(b);}
 saveCard=async function(){if(!signed){notify(t('먼저 로그인해 주세요.','Sign in first.'));return;}const snapshot=adapter.snapshot(model),duplicate=collection.some(c=>sameCard(c._raw?.data||adapter.snapshot(c),snapshot));if(duplicate&&!window.confirm(t('이미 저장된 명함인데 한번 더 저장하시겠습니까?','This card is already saved. Save it one more time?')))return;const id=crypto.randomUUID();collection.unshift({...structuredClone(model),id,group:'미분류',savedAt:new Date().toISOString(),_raw:{id,tab:'미분류',data:snapshot,savedAt:new Date().toISOString()}});persist();try{if(!guest)await account.flush();notify(t('명함함에 보관했습니다.','Saved to your collection.'));if(route()==='book')render();}catch(e){notify(err(e));}};
 exportDialog=async function(){openDialog('<div class="eyebrow">TAKE YOUR IDENTITY WITH YOU</div><h2>'+t('명함 저장과 공유','Save and share your card')+'</h2><p class="muted">'+t('선택한 공개 항목과 뒷면만 공유됩니다.','Only selected details and your card back are shared.')+'</p><div class="export-options"><button class="export-option" data-action="download-front">'+icon('image')+'<span><b>'+t('앞면 이미지','Front image')+'</b><small>PNG · 1440 × 800</small></span>'+icon('download')+'</button><button class="export-option" data-action="download-back">'+icon('image')+'<span><b>'+t('뒷면 이미지','Reverse image')+'</b><small>PNG · 1440 × 800</small></span>'+icon('download')+'</button><button class="export-option" data-action="download-vcf">'+icon('card')+'<span><b>'+t('연락처 파일','Contact file')+'</b><small>VCF / vCard</small></span>'+icon('download')+'</button><button class="export-option" data-action="save-card">'+icon('book')+'<span><b>'+t('명함함에 보관','Keep in collection')+'</b></span>'+icon('plus')+'</button></div><button class="button primary full" data-prod="publish">'+t('공유 링크·QR 만들기','Create share link and QR')+icon('arrow')+'</button><button class="text-button full" data-prod="manage-shares">'+t('내 공유 링크 관리','Manage my shared links')+'</button>');};
 async function publish(){const snapshot=adapter.snapshot(model),uid=account.state.user?.id;if(!snapshot.name&&!snapshot.fields.length)throw Error(t('공개할 정보를 하나 이상 선택해 주세요.','Select at least one public detail.'));let id;if(guest){id=crypto.randomUUID();try{const shares=JSON.parse(localStorage.getItem('damda-guest-shares')||'{}');shares[id]=snapshot;localStorage.setItem('damda-guest-shares',JSON.stringify(shares));}catch{throw Error(t('체험 공유 내용을 저장하지 못했습니다.','The demo share could not be saved.'));}}else{id=await account.publish(snapshot);if(uid!==account.state.user?.id)return;}published={id,url:baseURL()+'#card?id='+id};collection.unshift({...adapter.fromSnapshot(snapshot),id,group:'미분류',savedAt:new Date().toISOString(),_raw:{id,tab:'미분류',data:snapshot,savedAt:new Date().toISOString()}});persist();openDialog('<div class="eyebrow">READY TO CONNECT</div><h2>'+t('명함이 준비됐습니다.','Your card is ready.')+'</h2><div class="share-qr"><img id="share-qr" alt="'+t('명함 공유 QR 코드','Card QR code')+'"></div><label>'+t('공유 링크','Share link')+'<input id="share-url" readonly value="'+esc(published.url)+'"></label><div class="share-actions"><button class="button" data-prod="copy-share">'+t('링크 복사','Copy link')+'</button><a class="button" href="'+esc(published.url)+'" target="_blank" rel="noopener">'+t('명함 열기','Open card')+'</a><a class="button" id="qr-download" download="DamDa-QR.png">'+t('QR 저장','Save QR')+'</a>'+(navigator.share?'<button class="button" data-prod="native-share">'+t('공유하기','Share')+'</button>':'')+'</div><p class="local-note">'+t('링크를 아는 사람은 로그인 없이 볼 수 있습니다. 프로필 수정은 이미 만든 공유 링크에 반영되지 않습니다.','Anyone with the link can view this snapshot. Later profile edits do not change it.')+'</p>');const dialog=$('#dialog'),url=published.url;try{const png=await DamDaQR.toDataURL(url,{width:600,margin:4});if(dialog.open&&$('#share-qr')&&published?.url===url){$('#share-qr').src=png;$('#qr-download').href=png;}}catch{notify(t('QR 생성에 실패했습니다. 공유 링크를 사용해 주세요.','QR unavailable. Use the share link.'));}if(!guest)await account.flush();}
 async function manageShares(){const rows=guest?Object.entries(JSON.parse(localStorage.getItem('damda-guest-shares')||'{}')).map(([id,data])=>({id,data,created_at:new Date().toISOString()})):await account.listShares();openDialog('<div class="eyebrow">YOUR SHARED CARDS</div><h2>'+t('공유 링크 관리','Shared links')+'</h2><p class="muted">'+t('공유를 종료하면 해당 링크와 QR을 더 이상 열 수 없습니다.','Revoking a link also disables its QR code.')+'</p><div class="shared-links">'+(rows.length?rows.map(r=>'<article><div><b>'+esc(r.data.name||'DamDa')+'</b><small>'+esc(new Date(r.created_at).toLocaleDateString())+'</small></div><a class="text-button" target="_blank" rel="noopener" href="'+baseURL()+'#card?id='+esc(r.id)+'">'+t('열기','Open')+'</a><button class="text-button danger" data-revoke="'+esc(r.id)+'">'+t('공유 종료','Revoke')+'</button></article>').join(''):'<p>'+t('공유한 명함이 없습니다.','No shared cards yet.')+'</p>')+'</div>');}
 async function storeReceived(id,data){const duplicate=collection.some(c=>c._raw?.id===id||sameCard(c._raw?.data||adapter.snapshot(c),data));if(duplicate&&!window.confirm(t('이미 저장된 명함인데 한번 더 저장하시겠습니까?','This card is already saved. Save it one more time?')))return;if(duplicate)notify(t('같은 명함을 한 번 더 저장합니다.','Saving the same card again.'));collection.unshift({...adapter.fromSnapshot(data),id:crypto.randomUUID(),group:'미분류',_raw:{id,tab:'미분류',data,savedAt:new Date().toISOString()}});persist();if(!guest)await account.flush();notify(t('명함함에 저장했습니다.','Saved to your collection.'));}
 function renderShared(){const id=new URLSearchParams(location.hash.split('?')[1]).get('id')||'';if(!shared||shared.id!==id){const ticket=++sharedTicket;shared={id,loading:true};(guestShareRead(id)?Promise.resolve(guestShareRead(id)):account.readCard(id)).then(data=>{if(!data)throw Error(t('명함이 없거나 공유가 종료되었습니다.','Card unavailable.'));if(ticket!==sharedTicket)return;shared={id,data,model:adapter.fromSnapshot(data)};if(rawRoute()==='card')renderShared();}).catch(e=>{if(ticket!==sharedTicket)return;shared={id,error:err(e)};if(rawRoute()==='card')renderShared();});}const content=shared.loading?'<p role="status">'+t('명함을 불러오고 있습니다…','Loading card…')+'</p>':shared.error?'<h1>'+t('명함을 열 수 없습니다.','Card unavailable.')+'</h1><p role="alert">'+esc(shared.error)+'</p>':'<div class="eyebrow">NICE TO MEET YOU</div><h1>'+t('반가운 연결의 시작.','A new connection.')+'</h1><div id="live-card">'+cardMarkup(shared.model,true)+'</div><div class="preview-toolbar"><div class="segmented"><button data-action="front">'+t('앞면','Front')+'</button><button data-action="back">'+t('뒷면','Reverse')+'</button></div><button class="text-button" data-action="rotate-reset">'+t('회전 초기화','Reset view')+'</button></div><div class="share-actions"><button class="button" data-prod="public-front">'+t('앞면 PNG','Front PNG')+'</button><button class="button" data-prod="public-back">'+t('뒷면 PNG','Reverse PNG')+'</button><button class="button" data-prod="public-vcf">'+t('연락처 저장','Save contact')+'</button><button class="button primary" data-prod="save-received">'+t('명함함에 저장','Keep this card')+'</button></div>';
  $('#app').innerHTML='<div class="public-shell"><header class="login-header">'+brand()+settingButton()+'</header><main id="main" class="public-card">'+content+'<a class="text-button" href="#'+(signed?'home':'login')+'">'+t('내 DamDa로 이동','Go to my DamDa')+icon('arrow')+'</a></main></div>';observeCards();}

 // The collection viewer owns its rotation; editing the user's own card is unaffected.
 let viewerDrag=null;
 function viewerCard(){return $('#dialog.collection-viewer .detail-card .card-object');}
 function rotateViewer(x,y){const card=viewerCard();if(!card)return;card.dataset.rx=x;card.dataset.ry=y;card.querySelector('.card-rotator').style.transform='rotateX('+x+'deg) rotateY('+y+'deg)';card.parentElement.dataset.back=String(Math.cos(x*Math.PI/180)*Math.cos(y*Math.PI/180)<0);}
 function toggleCollectionViewer(){const dialog=$('#dialog'),detail=dialog.querySelector('.detail-card'),card=detail?.querySelector('.card-object');if(!card)return;viewerDrag=null;card.classList.remove('dragging');const expanded=dialog.classList.toggle('collection-viewer'),button=dialog.querySelector('[data-prod=collection-enlarge]');button.textContent=expanded?t('작게 보기','Reduce'):t('크게 보기','Enlarge');button.setAttribute('aria-expanded',String(expanded));if(expanded){card.tabIndex=0;card.setAttribute('role','group');card.setAttribute('aria-label',t('확대 명함. 드래그 또는 방향키로 회전','Enlarged card. Drag or use arrow keys to rotate'));card.setAttribute('aria-describedby','collection-viewer-help');rotateViewer(0,detail.dataset.back==='true'?180:0);card.focus({preventScroll:true});}else{card.removeAttribute('tabindex');card.removeAttribute('role');card.removeAttribute('aria-label');card.removeAttribute('aria-describedby');card.querySelector('.card-rotator').style.transform='rotateY('+(detail.dataset.back==='true'?180:0)+'deg)';button.focus({preventScroll:true});}dialog.scrollTop=0;observeCards();}
 document.addEventListener('pointerdown',e=>{const card=e.target.closest('.collection-viewer .card-object');if(!card||viewerDrag||!e.isPrimary||(e.pointerType==='mouse'&&e.button!==0))return;e.preventDefault();card.focus({preventScroll:true});viewerDrag={card,id:e.pointerId,x:e.clientX,y:e.clientY,rx:Number(card.dataset.rx)||0,ry:Number(card.dataset.ry)||0};card.setPointerCapture(e.pointerId);card.classList.add('dragging');});
 document.addEventListener('pointermove',e=>{if(!viewerDrag||viewerDrag.id!==e.pointerId)return;rotateViewer(viewerDrag.rx-(e.clientY-viewerDrag.y)*.5,viewerDrag.ry+(e.clientX-viewerDrag.x)*.6);});
 for(const event of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(event,e=>{if(viewerDrag?.id!==e.pointerId)return;const {card,id}=viewerDrag;viewerDrag=null;card.classList.remove('dragging');if(card.hasPointerCapture(id))card.releasePointerCapture(id);});
 document.addEventListener('keydown',e=>{const card=e.target.closest('.collection-viewer .card-object');if(!card||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home'].includes(e.key))return;e.preventDefault();let x=Number(card.dataset.rx)||0,y=Number(card.dataset.ry)||0;if(e.key==='Home'){x=0;y=0;}if(e.key==='ArrowLeft')y-=15;if(e.key==='ArrowRight')y+=15;if(e.key==='ArrowUp')x-=15;if(e.key==='ArrowDown')x+=15;rotateViewer(x,y);});
 $('#dialog').addEventListener('cancel',e=>{if(viewerCard()){e.preventDefault();toggleCollectionViewer();}});
 $('#dialog').addEventListener('close',()=>{viewerDrag=null;});
 function categoryManager(){openDialog('<div class="eyebrow">KEEP IT ORGANIZED</div><h2>'+t('분류 관리','Manage categories')+'</h2><p class="muted">'+t('분류 이름을 변경하거나 사용하지 않는 분류를 정리하세요.','Rename or remove your categories.')+'</p><button class="button" data-prod="category-add">'+icon('plus')+t('분류 추가','Add category')+'</button>'+(!allCategories().some(c=>c!=='미분류')?'<p class="collection-modal-empty">'+t('아직 추가한 분류가 없습니다.','No custom categories yet.')+'</p>':'')+allCategories().filter(c=>c!=='미분류').map((c,i)=>'<div class="category-edit"><input aria-label="'+t('분류 이름','Category name')+'" data-category-input="'+i+'" value="'+esc(c)+'" maxlength="30"><button class="button" data-category-rename="'+esc(c)+'" data-index="'+i+'">'+t('변경','Rename')+'</button><button class="text-button danger" data-category-delete="'+esc(c)+'">'+t('삭제','Delete')+'</button></div>').join('')+'<p class="local-note">'+t('삭제한 분류의 명함은 미분류로 이동합니다.','Cards in deleted categories move to Unsorted.')+'</p>');}
 document.addEventListener('click',e=>{
  const b=e.target.closest('button');if(!b)return;
  if(b.dataset.openCard){e.preventDefault();e.stopImmediatePropagation();const c=collection.find(c=>c.id===b.dataset.openCard);if(!c)return;openDialog('<div class="eyebrow">YOUR COLLECTION</div><h2>'+esc(c.name)+'</h2><div class="detail-card">'+cardMarkup(c,false)+'</div><p class="viewer-hint viewer-only" id="collection-viewer-help">'+t('드래그하거나 터치해 자유롭게 돌려보세요. 방향키로 회전 · Home으로 초기화','Drag or swipe to rotate freely. Arrow keys rotate · Home resets')+'</p><div class="share-actions"><button class="button" data-prod="collection-flip">'+t('앞뒷면 전환','Flip card')+'</button><button class="button" data-prod="collection-enlarge" aria-expanded="false">'+t('크게 보기','Enlarge')+'</button><button class="button viewer-only" data-prod="collection-reset">'+t('회전 초기화','Reset rotation')+'</button><button class="button" data-export-id="'+esc(c.id)+'" data-export-kind="png">PNG</button><button class="button" data-export-id="'+esc(c.id)+'" data-export-kind="vcf">VCF</button></div><label>'+t('분류','Category')+'<select id="card-group">'+[...new Set(['미분류',...categories,c.group])].map(v=>'<option value="'+esc(v)+'" '+(v===c.group?'selected':'')+'>'+esc(v)+'</option>').join('')+'<option value="__new__">'+t('+ 새 분류 추가','+ Add new category')+'</option></select></label><label id="card-group-new-row" hidden>'+t('새 분류 이름','New category name')+'<input id="card-group-new" maxlength="30"></label><div class="dialog-actions"><button class="button" data-update-group="'+esc(c.id)+'">'+t('분류 저장','Save category')+'</button><button class="text-button danger" data-delete-card="'+esc(c.id)+'">'+t('명함 삭제','Delete card')+'</button></div>');return;}
  if(b.dataset.updateGroup){e.preventDefault();e.stopImmediatePropagation();const c=collection.find(c=>c.id===b.dataset.updateGroup);if(!c)return;let name=$('#card-group').value;if(name==='__new__'){name=$('#card-group-new').value.trim();if(!name||name==='전체'||name==='__new__'){notify(t('새 분류 이름을 입력해 주세요.','Enter a category name.'));return;}if(!categories.includes(name)&&name!=='미분류')categories.push(name);}c.group=name;persist();closeDialog();filter='전체';page=1;render();return;}
  if(b.dataset.deleteCard){e.preventDefault();e.stopImmediatePropagation();if(!window.confirm(t('저장한 명함을 삭제할까요? 삭제한 명함은 복구할 수 없습니다.','Delete this saved card? This cannot be undone.')))return;collection=collection.filter(c=>c.id!==b.dataset.deleteCard);persist();closeDialog();render();return;}
  if(b.dataset.exportId){e.preventDefault();e.stopImmediatePropagation();const c=collection.find(c=>c.id===b.dataset.exportId);if(c)run(()=>b.dataset.exportKind==='vcf'?vcf(c):exportPNG($('#dialog .detail-card').dataset.back==='true',c),b);return;}
  if(b.dataset.revoke){e.preventDefault();e.stopImmediatePropagation();run(async()=>{if(guest){const shares=JSON.parse(localStorage.getItem('damda-guest-shares')||'{}');delete shares[b.dataset.revoke];localStorage.setItem('damda-guest-shares',JSON.stringify(shares));}else await account.revoke(b.dataset.revoke);await manageShares();},b);return;}
  if(b.dataset.categoryDelete){e.preventDefault();e.stopImmediatePropagation();const name=b.dataset.categoryDelete;if(!window.confirm(t('이 분류를 삭제할까요? 명함은 미분류로 이동합니다.','Delete this category? Cards will move to Unsorted.')))return;categories=categories.filter(c=>c!==name);collection.forEach(c=>{if(c.group===name)c.group='미분류';});filter='전체';persist();render();categoryManager();return;}
  if(b.dataset.categoryRename){e.preventDefault();e.stopImmediatePropagation();const old=b.dataset.categoryRename,name=$('[data-category-input="'+b.dataset.index+'"]').value.trim();if(!categoryNameValid(name,old)){notify(t('다른 분류 이름을 입력해 주세요.','Choose another name.'));return;}categories=allCategories().map(c=>c===old?name:c);collection.forEach(c=>{if(c.group===old)c.group=name;});filter='전체';persist();render();categoryManager();return;}
  if(b.dataset.modalFolder){e.preventDefault();e.stopImmediatePropagation();openCollectionEditor(b.dataset.modalFolder);return;}
  const action=b.dataset.prod||(b.dataset.action==='logout'?'logout':null);if(!action)return;e.preventDefault();e.stopImmediatePropagation();
  run(async()=>{
   if(action==='logout'){if(guest){guest=false;signed=false;location.hash='login';render();}else{await account.logout();location.hash='login';}}
   if(action==='guest-start'){guestStart();return;}if(action==='guest-signup'){location.hash='signup';return;}if(action==='retry-load')await account.retry();if(action==='retry-save')await account.flush();
   if(action==='backup')download(new Blob([JSON.stringify(adapter.encode(model,collection,customPresets,categories,original),null,2)],{type:'application/json'}),'DamDa-backup.json');
   if(action==='reload-account'){openDialog('<h2>'+t('계정 다시 불러오기','Reload account')+'</h2><p>'+t('아직 저장되지 않은 편집 내용은 사라집니다. 필요한 내용을 먼저 백업해 주세요.','Unsaved edits will be discarded. Back up your changes first.')+'</p><button class="button primary full" data-prod="confirm-reload">'+t('다시 불러오기','Reload')+'</button>');}
   if(action==='confirm-reload'){account.state.dirty=false;location.reload();}
   if(action==='forgot-dialog'){const typed=$('#login-email')?.value.trim()||'';openDialog('<div class="eyebrow">ACCOUNT RECOVERY</div><h2>'+t('비밀번호 찾기','Find your password')+'</h2><p class="muted">'+t('가입한 이메일을 입력하면 재설정 링크를 보내드립니다.','Enter your email and we will send a reset link.')+'</p><form id="forgot-form"><label>'+t('이메일','Email')+'<input name="email" type="email" autocomplete="email" maxlength="254" required value="'+esc(typed)+'"></label><p id="form-error" role="alert"></p><button class="button primary full">'+t('재설정 링크 보내기','Send reset link')+icon('arrow')+'</button></form>');}
   if(action==='password-dialog')openDialog('<h2>'+t('비밀번호 변경','Change password')+'</h2><form id="change-password-form">'+passwordField('change-password',t('새 비밀번호','New password'))+strength()+'<label>'+t('비밀번호 확인','Confirm password')+'<input name="confirm" type="password" minlength="8" maxlength="128" autocomplete="new-password" required></label>'+formError()+'<button class="button primary full">'+t('변경하기','Update')+'</button></form>');
   if(action==='publish')await publish();if(action==='manage-shares')await manageShares();
   if(action==='copy-share'){try{await navigator.clipboard.writeText(published.url);notify(t('명함 링크를 복사했습니다.','Link copied.'));}catch{$('#share-url').select();notify(t('선택된 주소를 복사해 주세요.','Copy the selected URL.'));}}
   if(action==='native-share'){try{await navigator.share({title:'DamDa',url:published.url});}catch(e){if(e.name!=='AbortError')throw e;}}
   if(action==='save-received'){if(!signed){sessionStorage.setItem('damda-pending-card',shared.id);location.hash='login';return;}await storeReceived(shared.id,shared.data);}
   if(action==='public-front')await exportPNG(false,shared.model);if(action==='public-back')await exportPNG(true,shared.model);if(action==='public-vcf')vcf(shared.model);
   if(action==='collection-enlarge')toggleCollectionViewer();
   if(action==='collection-reset')rotateViewer(0,0);
   if(action==='collection-flip'){const el=$('#dialog .detail-card'),back=el.dataset.back!=='true';if(viewerCard())rotateViewer(0,back?180:0);else{el.dataset.back=back;el.querySelector('.card-rotator').style.transform='rotateY('+(back?180:0)+'deg)';}}
   if(action==='category-add'){notice='';openDialog('<h2>'+t('분류 추가','Add category')+'</h2><form id="category-form"><label>'+t('분류 이름','Category name')+'<input name="category" maxlength="30" required></label>'+formError()+'<button class="button primary full">'+t('추가하기','Add category')+'</button></form>');}
   if(action==='category-manage')categoryManager();
  if(action==='collection-edit'||action==='collection-delete'){collectionMode=action==='collection-delete'?'delete':'edit';modalSelection.clear();modalTarget=allCategories()[0];openCollectionEditor('전체');}
  if(action==='category-mode'){collectionMode='category';openCategoryMode();}
  if(action==='modal-delete'){const ids=[...modalSelection];if(!ids.length){notify(t('삭제할 명함을 선택해 주세요.','Select cards to delete.'));return;}if(window.confirm(t(ids.length+'개의 명함을 삭제하시겠습니까?','Delete '+ids.length+' selected cards?'))){collection=collection.filter(c=>!ids.includes(c.id));persist();closeDialog();render();}}
  if(action==='modal-category-apply'){const ids=[...modalSelection],group=$('#modal-category')?.value;if(!ids.length){notify(t('분류할 명함을 선택해 주세요.','Select cards to categorize.'));return;}collection.forEach(c=>{if(ids.includes(c.id))c.group=group;});persist();closeDialog();render();notify(t('선택한 명함을 분류했습니다.','Selected cards were categorized.'));}
  },b);
 },true);
 // Clear all legacy demo/session caches. Supabase's own scoped session remains intact.
 for(const k of ['fold-profile','fold-session'])sessionStorage.removeItem(k);
 render();account.init();
})();
